/**
 * Notification presentation helpers for the Home activity feed: where a row
 * links to, and how its kind / action CTA are labelled.
 */

/**
 * Fall back to a notification's raw resource URL, or the owner's Memory page.
 */
export function notificationTarget(
	resourceUrl: string | null | undefined,
	currentOwner: string | null | undefined,
): string | null {
	const trimmed = resourceUrl?.trim();
	if (trimmed) return trimmed;
	if (currentOwner) return `/${currentOwner}/activity`;
	return null;
}

/** Short kind chip under the title on Home activity. */
export function notificationKindLabel(type: string): string {
	switch (type) {
		case "action_approval_needed":
			return "Needs approval";
		case "connection_permission_request":
			return "Authorization needed";
		case "browser_auth_expired":
			return "Sign-in required";
		case "invitation_received":
			return "Invitation";
		case "agent_message":
			return "Agent";
		default:
			return "Notification";
	}
}

/**
 * Explicit CTA when the user has something to *do*.
 * Returns null when row click is enough (digests) or when we lack a real target.
 */
export function notificationActionLabel(
	type: string,
	href?: string | null,
): string | null {
	// No destination → no lying CTA
	if (href == null || href === "") return null;

	switch (type) {
		case "action_approval_needed":
			return "Review & approve";
		case "connection_permission_request":
			return "Authorize connection";
		case "browser_auth_expired":
			return "Open connection";
		case "invitation_received":
			return "Accept invitation";
		default:
			return null;
	}
}
import { useInfiniteQuery, useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import {
  API_URL,
  type ApiOrgContext,
  fetchWithTimeout,
  resolveApiScope,
  tryResolveApiScopeSlug,
} from './core';

export interface NotificationItem {
  id: number;
  organization_id: string;
  user_id: string;
  type: string;
  title: string;
  body: string | null;
  resource_type: string | null;
  resource_id: string | null;
  resource_url: string | null;
  is_read: boolean;
  created_at: string;
}

function notificationsUrl(orgContext: ApiOrgContext | string, path = '') {
  const scope = resolveApiScope(orgContext);
  return `${API_URL}/api/${scope.slug}/notifications${path}`;
}

export function useUnreadNotificationCount(orgContext?: ApiOrgContext | string | null) {
  // Key on the resolved slug (a stable string), NOT the orgContext object.
  // The object gains `organizationId` once `/api/organizations` settles, which
  // would change object identity mid-load and trigger a second, redundant
  // fetch — the request URL only ever uses the slug, so the slug is the key.
  // Use the non-throwing resolver: this runs during render, and at the bare
  // root path (no org scope yet) the strict `resolveApiScope` would throw and
  // crash the tree.
  const scopeSlug = orgContext ? tryResolveApiScopeSlug(orgContext) : null;
  return useQuery({
    queryKey: ['notifications-unread-count', scopeSlug],
    queryFn: async () => {
      const res = await fetchWithTimeout(notificationsUrl(orgContext!, '/unread-count'), {
        credentials: 'include',
      });
      if (!res.ok) throw new Error('Failed to fetch unread count');
      const data = (await res.json()) as { count: number };
      return data.count;
    },
    enabled: !!orgContext,
    // SSE pushes `{ keys: ['notifications-unread-count'] }` on writes
    // (tools/admin/notify.ts:139), so route navigation alone doesn't need a refetch.
    staleTime: 60000,
  });
}

export function useNotifications(orgContext?: ApiOrgContext | string | null) {
  // Key on the resolved slug, not the orgContext object — see
  // useUnreadNotificationCount for why (avoids a duplicate fetch when the
  // org id arrives after the slug; non-throwing resolver, runs during render).
  const scopeSlug = orgContext ? tryResolveApiScopeSlug(orgContext) : null;
  return useInfiniteQuery({
    queryKey: ['notifications', scopeSlug],
    queryFn: async ({ pageParam }: { pageParam: number | null }) => {
      const params = new URLSearchParams();
      if (pageParam) params.set('cursor', String(pageParam));
      params.set('limit', '20');
      const url = `${notificationsUrl(orgContext!)}?${params}`;
      const res = await fetchWithTimeout(url, { credentials: 'include' });
      if (!res.ok) throw new Error('Failed to fetch notifications');
      return res.json() as Promise<{
        notifications: NotificationItem[];
        nextCursor: number | null;
      }>;
    },
    initialPageParam: null as number | null,
    getNextPageParam: (lastPage) => lastPage.nextCursor,
    enabled: !!orgContext,
  });
}

export function useMarkNotificationRead(orgContext?: ApiOrgContext | string | null) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: async (notificationId: number) => {
      const res = await fetchWithTimeout(notificationsUrl(orgContext!, `/${notificationId}/read`), {
        method: 'PATCH',
        credentials: 'include',
      });
      if (!res.ok) throw new Error('Failed to mark as read');
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['notifications-unread-count'] });
      queryClient.invalidateQueries({ queryKey: ['notifications'] });
    },
  });
}

export function useMarkAllNotificationsRead(orgContext?: ApiOrgContext | string | null) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: async () => {
      const res = await fetchWithTimeout(notificationsUrl(orgContext!, '/mark-all-read'), {
        method: 'POST',
        credentials: 'include',
      });
      if (!res.ok) throw new Error('Failed to mark all as read');
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['notifications-unread-count'] });
      queryClient.invalidateQueries({ queryKey: ['notifications'] });
    },
  });
}

