/**
 * Tool: save_memory
 *
 * Save content to the workspace, optionally associated with entities.
 * semantic_type is required and validated against $member.event_kinds for the org.
 * Entity metadata is validated against the entity type's schema.
 * Embeddings are left null for background worker backfill.
 */

import { normalizeAuthUserId, normalizeEmail } from '@lobu/connector-sdk/identity-normalize';
import { type Static, Type } from '@sinclair/typebox';
import { hasRequiredMcpScope } from '../auth/tool-access';
import { resolveChannelEntityId } from '../authz/channel-entity';
import { getDb } from '../db/client';
import type { Env } from '../index';
import { autoLinkEvent } from '../utils/auto-linker';
import { ToolUserError } from '../utils/errors';
import { validateSaveContentSemanticType } from '../utils/event-kind-validation';
import { getConfiguredEmbeddingModel, needsEmbeddingSql } from '../utils/embeddings';
import { insertEvent } from '../utils/insert-event';
import logger from '../utils/logger';
import {
  assertCanAuthorGuidance,
  assertCanRemoveGuidance,
  GUIDANCE_SEMANTIC_TYPE,
} from '../utils/org-guidance';
import { ensureMemberEntityType } from '../utils/member-entity-type';
import { requireWriteAccess } from '../utils/organization-access';
import { validateTemplateHandlers } from '../utils/validate-json-template';
import { trackWatcherReaction } from '../utils/watcher-reactions';
import { isSystemContext } from './access-control';
import { MEMBER_ENTITY_TYPE_SLUG } from './constants';
import type { ToolContext } from './registry';
import { withValidatedArgs } from './validate-args';
import { buildEventViewUrl } from './view-urls';

/**
 * True when a Postgres error is the unique-violation (23505) on the partial
 * index that guards "at most one event supersedes a given target". The loser
 * of a concurrent-supersede race hits this; postgres.js exposes the SQLSTATE
 * on `code` and the index name on `constraint`/`constraint_name`.
 */
function isSupersededByUniqueViolation(error: unknown): boolean {
  const err = error as {
    code?: unknown;
    constraint?: unknown;
    constraint_name?: unknown;
    message?: unknown;
  };
  if (err?.code !== '23505') return false;
  return (
    err.constraint === 'idx_events_superseded_by' ||
    err.constraint_name === 'idx_events_superseded_by' ||
    (typeof err.message === 'string' && err.message.includes('idx_events_superseded_by'))
  );
}

// ============================================
// Typebox Schema
// ============================================

export const SaveContentSchema = Type.Object({
  entity_ids: Type.Optional(
    Type.Array(Type.Number(), {
      description: 'Entity IDs to associate content with. Omit for org-scoped content.',
    })
  ),
  content: Type.Optional(
    Type.String({
      description: 'The text content to save. Required for text/markdown payload types.',
    })
  ),
  title: Type.Optional(Type.String({ description: 'Short title or summary' })),
  author: Type.Optional(Type.String({ description: 'Author name or identifier' })),
  semantic_type: Type.Optional(
    Type.String({
      description:
        'Semantic type (e.g. note, summary, decision, identity, observation). Preferred.',
    })
  ),
  payload_type: Type.Optional(
    Type.Union(
      [
        Type.Literal('text'),
        Type.Literal('markdown'),
        Type.Literal('json_template'),
        Type.Literal('media'),
        Type.Literal('empty'),
      ],
      {
        description:
          "Content format. 'text' (default): plain text. 'markdown': rendered as rich text. 'json_template': rendered via payload_template + payload_data. 'media': media-focused display. 'empty': metadata only.",
      }
    )
  ),
  payload_data: Type.Optional(
    Type.Record(Type.String(), Type.Any(), {
      description:
        'Structured data object. Used as template data for json_template, or structured metadata for media.',
    })
  ),
  payload_template: Type.Optional(
    Type.Record(Type.String(), Type.Any(), {
      description:
        'JSON template for rendering. Required when payload_type is json_template. Must have a { root: ... } structure.',
    })
  ),
  attachments: Type.Optional(
    Type.Array(Type.Record(Type.String(), Type.Any()), {
      description: 'Array of attachment objects (e.g. files, images).',
    })
  ),
  source_url: Type.Optional(
    Type.String({ description: 'URL of the original source for this content.' })
  ),
  occurred_at: Type.Optional(
    Type.String({
      description: 'When the event actually happened (ISO 8601). Defaults to now if omitted.',
    })
  ),
  metadata: Type.Record(Type.String(), Type.Any(), {
    description:
      'Structured metadata — validated against the entity type schema or semantic_type schema',
  }),
  supersedes_event_id: Type.Optional(
    Type.Number({
      description:
        'ID of an existing event this content replaces (e.g. updated preference, corrected fact). The old event is marked as superseded and excluded from future searches.',
    })
  ),
  behavior_source: Type.Optional(
    Type.Object(
      {
        behavior_id: Type.Number({ description: 'Behavior that triggered this save' }),
        window_id: Type.Number({ description: 'Window that triggered this save' }),
      },
      { description: 'Attribution source when save is triggered by a Behavior reaction' }
    )
  ),
});

type SaveContentArgs = Static<typeof SaveContentSchema>;

// ============================================
// Result Type
// ============================================

interface SaveContentResult {
  id: number;
  entity_ids: number[];
/**
 * ClientSDK `knowledge` namespace.
 *
 * Wraps the `search_memory`, `save_memory`, and `read_knowledge` handlers.
 * `deleteContent` is SDK-only, exposed as `client.knowledge.delete` rather
 * than as a registered MCP tool.
 */

import type { Env } from "../../index";
import { deleteContent } from "../../tools/delete_content";
import { getContent } from "../../tools/get_content";
import type { ToolContext } from "../../tools/registry";
import { saveContent } from "../../tools/save_content";
import { search } from "../../tools/search";

export interface KnowledgeSearchInput {
	query?: string;
	entity_type?: string;
	entity_id?: number;
	parent_id?: number;
	market?: string;
	category?: string;
	fuzzy?: boolean;
	min_similarity?: number;
	include_connections?: boolean;
	include_content?: boolean;
	limit?: number;
}

export interface KnowledgeSaveInput {
	entity_ids?: number[];
	content: string;
	semantic_type: string;
	metadata?: Record<string, unknown>;
	title?: string;
	slug?: string;
}

export interface KnowledgeReadInput {
	/** Fetch specific content events by id. */
	content_ids?: number[];
	/** Fetch structured knowledge for a Behavior window. */
	behavior_id?: number;
	since?: string;
	until?: string;
	limit?: number;
	before_occurred_at?: string;
	before_id?: number;
	entity_ids?: number[];
}

export type KnowledgeDeleteInput =
	| number
	| { content_id?: number; content_ids?: number[]; reason?: string };

export interface KnowledgeNamespace {
	search(input: KnowledgeSearchInput): Promise<unknown>;
	save(input: KnowledgeSaveInput): Promise<unknown>;
	read(input: KnowledgeReadInput): Promise<unknown>;
	delete(input: KnowledgeDeleteInput): Promise<unknown>;
}

export function buildKnowledgeNamespace(
	ctx: ToolContext,
	env: Env,
): KnowledgeNamespace {
	return {
		search(input) {
			return search(input as never, env, ctx) as Promise<unknown>;
		},
		save(input) {
			return saveContent(input as never, env, ctx) as Promise<unknown>;
		},
		read(input) {
			return getContent(input as never, env, ctx) as Promise<unknown>;
		},
		delete(input) {
			const args =
				typeof input === "number" ? { content_id: input } : (input ?? {});
			return deleteContent(args as never, env, ctx) as Promise<unknown>;
		},
	};
}
/**
 * ClientSDK `notifications` namespace.
 *
 * `send` wraps the `notify` tool (in-app inbox + bot fan-out). `list` /
 * `markRead` reuse the REST service layer (`listNotifications` / `markAsRead`)
 * so callers can read and ack their own inbox without duplicate SQL. Reading
 * is available through `query_sdk`; acknowledging changes state and requires
 * `run_sdk`.
 */

import type { CardElement } from "chat";
import type { Env } from "../../index";
import { listNotifications, markAsRead } from "../../notifications/service";
import { notify } from "../../tools/admin/notify";
import type { ToolContext } from "../../tools/registry";
import { ToolUserError } from "../../utils/errors";
import { createActionCaller, idArg } from "./action-call";

export interface NotificationsSendInput {
	/** Notification title (≤200 chars). */
	title: string;
	/** Body text (≤1000 chars). */
	body?: string;
	/**
	 * Optional rich card (`chat` `CardElement`) for bot-connection delivery,
	 * rendered to each platform's native format (Block Kit / Adaptive Cards / …).
	 */
	card?: CardElement;
	/**
	 * Who to notify. `"admins"` (default): org admins/owners. `"all"`: every
	 * member. Or an array of specific user IDs.
	 */
	recipients?: "admins" | "all" | string[];
	/** Relative URL the notification links to (e.g. `/acme/entities`). */
	resource_url?: string;
	/** Deliver only through this specific bot connection (its id). */
	connection_id?: string;
	/** Arbitrary JSON payload appended to the body as formatted JSON. */
	data?: Record<string, unknown>;
	/** Attribution when sent from a watcher reaction — both ids are numeric. */
	behavior_source?: { behavior_id: number; window_id: number };
}

export interface NotificationsListInput {
	/** Keyset cursor: return notifications with id strictly less than this. */
	cursor?: number | null;
	/** Page size (service caps at 50; default 20). */
	limit?: number;
	/** When true, only unread notifications. */
	unread_only?: boolean;
}

export interface NotificationsListResult {
	notifications: Record<string, unknown>[];
	nextCursor: number | null;
}

export interface NotificationsNamespace {
	send(input: NotificationsSendInput): Promise<{ notified_count: number }>;
	list(input?: NotificationsListInput): Promise<NotificationsListResult>;
	/**
	 * Mark one of the caller's notifications as read. Accepts a positional id
	 * or `{ notification_id }`.
	 */
	markRead(
		notificationId: number | { notification_id: number },
	): Promise<{ success: true }>;
}

function requireUserId(ctx: ToolContext): string {
	if (!ctx.userId) {
		throw new ToolUserError("Authenticated user required", 401);
	}
	return ctx.userId;
}

export function buildNotificationsNamespace(
	ctx: ToolContext,
	env: Env,
): NotificationsNamespace {
	const { action } = createActionCaller(notify, env, ctx, "notifications");

	return {
		send: (input) => action("send", input),
		async list(input) {
			const userId = requireUserId(ctx);
			return listNotifications({
				organizationId: ctx.organizationId,
				userId,
				cursor: input?.cursor ?? null,
				limit: input?.limit,
				unreadOnly: input?.unread_only ?? false,
			});
		},
		async markRead(notificationId) {
			const userId = requireUserId(ctx);
			const id = idArg(
				"notifications.markRead",
				"notification_id",
				notificationId,
				"number",
			) as number;
			const updated = await markAsRead(ctx.organizationId, userId, id);
			if (!updated) {
				throw new ToolUserError("Not found or already read", 404);
			}
			return { success: true as const };
		},
	};
}

