/**
 * Custom TanStack Router history that transparently maps `/foo` ↔ `/${owner}/foo`
 * on per-org subdomains. The router always sees the prefixed path (so
 * `/$owner/...` routes match), while the URL bar never shows the redundant
 * owner segment.
 *
 * Top-level segments that are NOT under `$owner` (auth, oauth, account) are
 * passed through unchanged in both directions.
 */

import { createBrowserHistory, type RouterHistory } from '@tanstack/react-router';

const NON_OWNER_TOP_LEVELS = new Set(['auth', 'oauth', 'account']);

function isOwnerPath(pathname: string): boolean {
  if (pathname === '/' || pathname === '') return true;
  const firstSeg = pathname.split('/')[1] ?? '';
  return !NON_OWNER_TOP_LEVELS.has(firstSeg);
}

function splitHref(href: string): { path: string; rest: string } {
  const match = href.match(/^([^?#]*)(.*)$/);
  return { path: match?.[1] ?? href, rest: match?.[2] ?? '' };
}

export function addOwnerPrefix(pathname: string, owner: string): string {
  const prefix = `/${owner}`;
  if (!isOwnerPath(pathname)) return pathname;
  if (pathname === prefix || pathname.startsWith(`${prefix}/`)) return pathname;
  if (pathname === '/' || pathname === '') return prefix;
  return `${prefix}${pathname}`;
}

export function stripOwnerPrefix(href: string, owner: string): string {
  const prefix = `/${owner}`;
  const { path, rest } = splitHref(href);
  if (path === prefix) return `/${rest}`;
  if (path.startsWith(`${prefix}/`)) return `${path.slice(prefix.length)}${rest}`;
  return href;
}

function buildLocation(href: string, state: unknown) {
  const hashIndex = href.indexOf('#');
  const searchIndex = href.indexOf('?');
  const pathnameEnd =
    hashIndex > 0
      ? searchIndex > 0
        ? Math.min(hashIndex, searchIndex)
        : hashIndex
      : searchIndex > 0
        ? searchIndex
        : href.length;
  const pathname = href.substring(0, pathnameEnd);
  const search = searchIndex > -1 ? href.slice(searchIndex, hashIndex === -1 ? undefined : hashIndex) : '';
  const hash = hashIndex > -1 ? href.substring(hashIndex) : '';
  return {
    href,
    pathname,
    search,
    hash,
    state: (state ?? {}) as Record<string, unknown> & { __TSR_index: number },
  };
}

export function createSubdomainHistory(owner: string): RouterHistory {
  return createBrowserHistory({
    parseLocation: () => {
      const pathname = addOwnerPrefix(window.location.pathname, owner);
      const href = `${pathname}${window.location.search}${window.location.hash}`;
      return buildLocation(href, window.history.state);
    },
    createHref: (path) => stripOwnerPrefix(path, owner),
  });
}
/**
 * SPA-side mirror of the backend's subdomain → org slug extraction.
 *
 * Keep the reserved-subdomain list in sync with `RESERVED_SUBDOMAINS` in
 * `packages/server/src/index.ts` and the `extractSubdomainOrg` /
 * `getSubdomainZone` helpers in `packages/server/src/utils/public-origin.ts`.
 *
 * The zone is declared by the server at runtime (`window.__LOBU_RUNTIME_CONFIG__`)
 * from AUTH_COOKIE_DOMAIN. No zone declared → no subdomain routing, and the app
 * stays on path-based `/{org}` URLs.
 *
 * It is deliberately NOT inferred from `window.location.hostname`. Guessing the
 * zone by stripping the last two labels reads the first label of any ordinary
 * 3-label host as an org slug, so a self-hoster on `service.my-domain.com` was
 * redirected to `{org}.my-domain.com` — a host their reverse proxy did not
 * serve — and the app 404'd (lobu#2183). A build-time flag could not fix that
 * either: Docker self-hosters run a prebuilt frontend and cannot set a Vite var.
 */

const RESERVED_SUBDOMAINS = new Set([
  'www',
  'api',
  'app',
  'admin',
  'auth',
  'mcp',
  'static',
  'assets',
  'cdn',
  'docs',
  'mail',
]);

/** The zone the server declared, or null when routing stays path-based. */
export function getSubdomainZone(): string | null {
  if (typeof window === 'undefined') return null;
  return window.__LOBU_RUNTIME_CONFIG__?.subdomainZone ?? null;
}

export function extractSubdomainOwner(hostname: string, zone: string | null): string | null {
  if (!zone) return null;
  const normalizedHost = hostname.split(':')[0]?.toLowerCase();
  if (!normalizedHost || !normalizedHost.endsWith(`.${zone}`)) return null;

  const sub = normalizedHost.slice(0, -(zone.length + 1));
  if (!sub || sub.includes('.') || RESERVED_SUBDOMAINS.has(sub)) return null;
  return sub;
}

let cached: string | null | undefined;

/** Test-only: clears the owner memoized at application boot. */
export function __resetSubdomainCacheForTests(): void {
  cached = undefined;
}

export function getSubdomainOwner(): string | null {
  if (cached !== undefined) return cached;
  if (typeof window === 'undefined') {
    cached = null;
    return cached;
  }
  cached = extractSubdomainOwner(window.location.hostname, getSubdomainZone());
  return cached;
}

/**
 * Builds the URL for an org's workspace home given the current host.
 * - With a configured zone, returns the target's absolute org URL unless the
 *   browser is already on that org's subdomain.
 * - Without a configured zone, returns the path-based in-app URL.
 */
export function buildOwnerHref(targetSlug: string): { kind: 'spa'; to: string } | { kind: 'cross-host'; href: string } {
  const zone = getSubdomainZone();
  if (!zone) {
    return { kind: 'spa', to: `/${targetSlug}` };
  }
  const currentSubdomain = getSubdomainOwner();
  if (currentSubdomain === targetSlug) {
    return { kind: 'spa', to: '/' };
  }
  const protocol = typeof window !== 'undefined' ? window.location.protocol : 'https:';
  return { kind: 'cross-host', href: `${protocol}//${targetSlug}.${zone}/` };
