/** Split an app-relative href into path + search for TanStack Router. */
export function parseAppHref(href: string): {
	pathname: string;
	search: Record<string, string> | undefined;
} {
	const trimmed = href.trim();
	const q = trimmed.indexOf("?");
	if (q < 0) return { pathname: trimmed, search: undefined };
	const pathname = trimmed.slice(0, q) || "/";
	const params = new URLSearchParams(trimmed.slice(q + 1));
	const search: Record<string, string> = {};
	for (const [k, v] of params) {
		search[k] = v;
	}
	return {
		pathname,
		search: Object.keys(search).length > 0 ? search : undefined,
	};
}

