  triggers: [{ kind: "schedule", cron: "0 * * * *" }],
  notification: { channel: "both", priority: "normal" },
  minCooldownSeconds: 300,
  keyingConfig: {
    entityType: "task",
    entityPath: "tasks",
    keyFields: ["action"],
