/**
 * Promote keyed watcher-window rows into real child entities (P2 phase 1).
 *
 * `computeStableKeys()` stamps a deterministic stable-key string onto each
 * extracted entity (at `keyingConfig.key_output_field`). That key dead-ended:
 * nothing turned the keyed rows into rows in the `entities` table. This module
 * closes that gap. For each keyed row it upserts a child entity, idempotent by
 * stable key. The stable key is persisted as an `entity_identities` row in a
 * dedicated `watcher_key` namespace (identifier = `<watcherId>::<stableKey>`),
 * so a re-run — or a second replica racing the same window — resolves to the
 * existing entity instead of creating a duplicate. The partial unique index
 * `idx_entity_identities_live_unique (organization_id, namespace, identifier)
 * WHERE deleted_at IS NULL` is the lock.
 *
 * Origin provenance (the window that first produced the entity, its stable key,
 * and the watcher) is stamped onto the entity's own `metadata` at creation —
 * `metadata.window_id` / `stable_key` / `watcher_id`. There is NO separate
 * observation event: an entity is promoted once (it's an identity, not a time
 * series), so its origin lives on the row itself.
 *
 * The upsert runs on the caller's transaction handle so the entity and identity
 * writes commit atomically with the window itself.
 *
 * Multi-replica notes:
 *   - `entities.id` / `entity_identities.id` are `nextval()` sequence columns,
 *     so concurrent inserts never collide on the PK (no advisory-lock allocator
 *     needed here — that's only for the MAX(id)+1 tables).
 *   - The window (canvas chain root) is guarded by `idx_canvas_chain_root`, so at
 *     most one completion creates a given window; idempotent replays reuse it and
 *     re-enter this function, where the per-key identity claim makes repeats
 *     no-ops.
 *   - `fetch_types: false`: never bind a raw JS array — all identifiers here are
 *     scalar params.
 */

import { slugify } from '@lobu/core';
import { ApprovalAttribution } from '@lobu/core/contracts/interaction-envelope';
import {
  deferEntityCreate,
  deferEntityFieldChange,
  type DeferredMutation,
  runMutationGate,
} from '../authz/entity-mutation-gate';
import {
  mutationPrincipalId,
  resolveWatcherOwner,
} from '../authz/entity-policy';
import type { DbClient } from '../db/client';
import type { KeyingConfig } from '../types/watchers';
import {
  type AppliedChange,
  type BlockedChange,
  mergeEntityFields,
} from './entity-field-merge';
import { getValueAtPath } from './object-path';
import logger from './logger';
import { isUniqueViolation } from './pg-errors';

/** Namespace for the stable-key identity claim in `entity_identities`. */
const WATCHER_KEY_NAMESPACE = 'watcher_key';

/** Agent-authored field naming the content a promoted row came from. */
const SOURCE_EVENT_ID_FIELD = 'source_event_id';

export interface PromoteKeyedEntitiesParams {
  /** Transaction-bound SQL handle (MUST be the window-write transaction). */
  tx: DbClient;
  /** Extracted data AFTER `computeStableKeys` has stamped the keys. */
  extractedData: Record<string, unknown>;
  keyingConfig: KeyingConfig;
  watcherId: number;
  organizationId: string;
  /** The finalized window identity (canvas ROOT event id) this completion produced/reused. */
  windowId: number;
  /**
   * The exact content IDs the window_token granted for this completion.
   * A promoted row may cite its origin via `source_event_id`; that value comes
   * from agent output and is otherwise stored verbatim, so an agent could point
   * a promotion at content its window never read. Citations outside this set are
   * dropped (the row still promotes — only the unverifiable claim is removed).
   */
  validContentIds: Set<number>;
  /** The watcher's bound parent entity (entity_ids[0]); null when unbound. */
  parentEntityId: number | null;
  /**
   * Attribution for created entities — MUST be a live `user(id)` because
   * `entities.created_by` is NOT NULL with an ON DELETE RESTRICT FK. The
   * watcher's own `created_by` satisfies this. When null, an org owner/admin is
   * resolved as a fallback; if none exists, entity creation is skipped.
   */
  createdBy?: string | null;
}

/**
 * One entity this run touched inline, for the first-class run change-set. Emitted
 * for auto-applied changes too — the diff is a property of the run, not of the
 * approval flow, so a fully-auto watcher run still shows exactly what it changed.
 */
export interface PromotedEntityChange {
  entityId: number;
  name: string;
  /** `created` = brand-new entity; `updated` = existing entity whose fields changed. */
  kind: 'created' | 'updated';
  /** For `updated`, the fields written inline (old→new). Empty for `created`. */
  applied: Record<string, AppliedChange>;
}

export interface PromoteKeyedEntitiesResult {
  /** Number of distinct keyed rows that resolved to an entity. */
  promoted: number;
  /** Of those, how many created a brand-new entity (vs. matched an existing). */
  created: number;
  /**
   * Owned-field / policy-gated changes and policy-held creates that were NOT
   * applied — packaged as deferred approvals the caller flushes POST-COMMIT
   * (never writing inline, never on the caller's tx).
   */
  deferred: DeferredMutation[];
  /**
   * The applied change-set: every entity this run created or updated inline. The
   * caller records this as a first-class event on the run so the change is
   * visible on the run itself, independent of any approval.
   */
  changes: PromotedEntityChange[];
}

/**
 * A stable key is "non-empty" when at least one of its `::`-joined segments
 * carries a slug. `computeStableKeys` emits `"stability::"` / `"::app-crashes"`
 * when one field is null — those are still meaningful and DO promote. Only an
 * all-empty key (`""`, `"::"`, `"::::"`) is skipped.
 */
function hasNonEmptyKey(stableKey: unknown): stableKey is string {
  if (typeof stableKey !== 'string') return false;
  return stableKey.split('::').some((segment) => segment.length > 0);
}

/**
 * Resolve a live `user(id)` to attribute created entities to. Prefers the
 * caller-supplied `created_by` (the watcher's creator — already a live user);
 * otherwise falls back to an org owner/admin, mirroring entity-link-upsert's
 * `resolveOrgCreator`. Returns null when the org has no member to attribute to.
 */
async function resolveCreator(
  tx: DbClient,
  organizationId: string,
  createdBy: string | null | undefined
): Promise<string | null> {
  if (createdBy && createdBy.trim().length > 0) return createdBy;
  const rows = await tx<{ userId: string }>`
    SELECT "userId"
    FROM "member"
    WHERE "organizationId" = ${organizationId}
    ORDER BY CASE role WHEN 'owner' THEN 0 WHEN 'admin' THEN 1 ELSE 2 END,
             "createdAt" ASC
    LIMIT 1
  `;
  return rows.length > 0 ? rows[0].userId : null;
}


/**
 * Resolve the target entity-type slug. Prefer the explicit `keying_config`
 * field; otherwise derive a singular-ish slug from the last segment of
 * `entity_path` (`analysis.results.problems` → `problem`).
 */
function resolveEntityTypeSlug(config: KeyingConfig): string {
  if (config.entity_type && config.entity_type.trim().length > 0) {
    return config.entity_type.trim();
  }
  const lastSegment = config.entity_path.split('.').pop() ?? config.entity_path;
  const base = slugify(lastSegment);
  // Light singularization so `problems` → `problem`, `categories` → `category`.
  if (base.endsWith('ies')) return `${base.slice(0, -3)}y`;
  if (base.endsWith('s') && !base.endsWith('ss')) return base.slice(0, -1);
  return base || 'item';
}

/**
 * Build a human-readable entity name from RAW field values (not the slugified
 * key). Falls back to the stable key when no field carries a value.
 *
 * Prefers `name_fields` and falls back to `key_fields`. The two are separate on
 * purpose: a stable key must never change between runs, so it is usually an
 * opaque id (`li_home_DijYQ…`), which makes a terrible display name. Keying on
 * the readable field instead would tie the entity's identity to a value that can
 * be edited upstream — a renamed author would orphan the entity and promote a
 * duplicate.
 */
export function buildEntityName(
  entityRecord: Record<string, unknown>,
  config: KeyingConfig,
  stableKey: string
): string {
  const nameFields =
    config.name_fields && config.name_fields.length > 0 ? config.name_fields : config.key_fields;
  const parts = nameFields
    .map((field) => entityRecord[field])
    .filter((v): v is string | number => v !== null && v !== undefined && String(v).trim().length > 0)
    .map((v) => String(v).trim());
  const joined = parts.join(' · ');
  return joined.length > 0 ? joined : stableKey;
}

/**
 * Resolve an entity-type slug → entity_types(id), searching the watcher's own
 * org first then any public catalog (same precedence as createEntity). Skips
 * derived (view-backed) types — they have no stored rows to insert into.
 */
async function resolveEntityTypeId(
  tx: DbClient,
  organizationId: string,
  entityTypeSlug: string
): Promise<number | null> {
  const rows = await tx<{ id: number; backing_sql: string | null }>`
    SELECT et.id, et.backing_sql
    FROM entity_types et
    LEFT JOIN organization o ON o.id = et.organization_id
    WHERE et.slug = ${entityTypeSlug}
      AND et.deleted_at IS NULL
      AND (
        et.organization_id = ${organizationId}
        OR o.visibility = 'public'
      )
    ORDER BY (et.organization_id = ${organizationId}) DESC, et.id ASC
    LIMIT 1
  `;
  if (rows.length === 0) return null;
  if (rows[0].backing_sql) return null;
  return Number(rows[0].id);
}

/**
 * How many readable numeric suffixes (`-2`, `-3`, …) to try before falling back
 * to a guaranteed-unique identifier-derived slug. Keeps slugs human-friendly
 * while guaranteeing the insert terminates.
 */
const SLUG_DISAMBIGUATION_ATTEMPTS = 5;

/**
 * Insert the child entity, tolerating a slug collision on
 * `entities_slug_parent_unique (organization_id, COALESCE(parent_id,0), slug)`.
 * Two keyed rows can slugify to the same base slug, and the slug can clash with
 * a pre-existing sibling. A raw INSERT would then throw 23505 and — because
 * promotion runs inside the window-completion transaction — roll the whole
 * completion back; since the slug is deterministic, every retry re-hits it and
 * the window is permanently poison-pilled. The entity's real identity is its
 * `watcher_key` claim, so the slug is cosmetic: retry with `-2`, `-3`, … and
 * finally an identifier-derived suffix (unique per watcher+key). Each attempt is
 * savepoint-isolated so a failed INSERT doesn't abort the outer transaction.
 */
async function insertEntityWithUniqueSlug(params: {
  tx: DbClient;
  organizationId: string;
  entityTypeId: number;
  parentEntityId: number | null;
  name: string;
  baseSlug: string;
  identifier: string;
  metadata: Record<string, unknown>;

async function saveContentImpl(
  args: SaveContentArgs,
  _env: Env,
  ctx: ToolContext
): Promise<SaveContentResult> {
  // SDK delegates (`client.knowledge.save`) skip `checkToolAccess`, so apply
  // the same member+scope gate here. System contexts (userId=null + auth=true)
  // bypass — watcher reactions don't carry a user identity.
  if (!isSystemContext(ctx)) {
    if (!ctx.memberRole) {
      throw new ToolUserError('save_memory requires workspace membership with write access.', 403);
    }
    if (!hasRequiredMcpScope('write', ctx.scopes)) {
      throw new ToolUserError('save_memory requires an MCP session with write access.', 403);
    }
  }

  const sql = getDb();

  // 0. Ensure $member entity type exists for this org
  await ensureMemberEntityType(ctx.organizationId);

  const entityIds: number[] = args.entity_ids ?? [];
  const semanticType = args.semantic_type;
  if (!semanticType) throw new ToolUserError('semantic_type is required');

  // `guidance` is the built-in org-wide context kind: current guidance events
  // are injected into EVERY agent's system prompt (workspace instructions +
  // worker session context), which makes authorship a prompt-injection
  // surface. Fail closed: only org owners/admins may author it — system
  // contexts (watcher reactions, memberRole=null) and plain members are
  // rejected. This is the single choke point for both the MCP tool and the
  // SDK delegate (`client.knowledge.save`).
  const isOrgGuidance = semanticType === GUIDANCE_SEMANTIC_TYPE;
  assertCanAuthorGuidance(semanticType, ctx.memberRole);

  const payloadType = args.payload_type ?? 'text';

  // Guidance renders from `payload_text` only (loadOrgGuidanceBlock), so a
  // media/json_template/empty guidance event would save yet render as nothing.
  // Constrain authorship to non-whitespace text/markdown rather than silently
  // storing an un-renderable row.
  if (isOrgGuidance) {
    if (payloadType !== 'text' && payloadType !== 'markdown') {
      throw new ToolUserError(
        `semantic_type '${GUIDANCE_SEMANTIC_TYPE}' requires payload_type 'text' or 'markdown'.`,
        422
      );
    }
    if (!args.content || !args.content.trim()) {
      throw new ToolUserError(
        `semantic_type '${GUIDANCE_SEMANTIC_TYPE}' requires non-empty content.`,
        422
      );
    }
  }

  // Validate content requirement based on payload_type
  if ((payloadType === 'text' || payloadType === 'markdown') && !args.content) {
    throw new ToolUserError(`content is required for payload_type '${payloadType}'`);
  }
  if (payloadType === 'json_template' && !args.payload_template) {
    throw new ToolUserError("payload_template is required when payload_type is 'json_template'");
  }
  // Events retain their existing permissive template shape, but handler values
  // must use the renderer's action-binding syntax.
  if (payloadType === 'json_template') {
    try {
      validateTemplateHandlers(args.payload_template);
    } catch (err) {
      throw new ToolUserError((err as Error).message, 422);
    }
  }

  // 1. Require write access for each entity
  for (const eid of entityIds) {
    await requireWriteAccess(sql, eid, ctx);
  }

  // 2. Validate semantic_type against $member.event_kinds + entity type event_kinds.
  //    `guidance` is a built-in org-wide kind registered in the $member
  //    event_kinds registry (ensureMemberEntityType), so it validates through
  //    this same path as every other kind — no code-level bypass. Its admin-only
  //    authorship/removal gates (org-guidance.ts) are orthogonal and applied
  //    above/below. See issue #1913.
  const kindValidation = await validateSaveContentSemanticType(
    semanticType,
    args.metadata,
    ctx.organizationId,
    entityIds.length > 0 ? entityIds : undefined
  );
  if (!kindValidation.valid) {
    throw new ToolUserError(kindValidation.errors.join('\n'), 422);
  }

  // 3. Validate event metadata against entity type's event kind schema (if entity-associated)
  //    Note: entity type metadata_schema is for entity creation/update, not for events.
  //    Event metadata is already validated against event_kinds metadataSchema in step 2.

  // 4. Resolve $member entity for this user via entity_identities and append to entity_ids.
  //    Identity lookup order:
  //      1) auth_user_id namespace (already linked in a prior call)
  //      2) email namespace (user has a member entity claimed by some connector); claim auth_user_id
  const finalEntityIds = [...entityIds];
  if (ctx.userId) {
    const authId = normalizeAuthUserId(ctx.userId);
    let memberRows: Array<{ id: number | string }> = [];

    if (authId) {
      memberRows = await sql`
        SELECT e.id
        FROM entity_identities ei
        JOIN entities e ON e.id = ei.entity_id
        JOIN entity_types et ON et.id = e.entity_type_id
        WHERE ei.organization_id = ${ctx.organizationId}
          AND ei.namespace = 'auth_user_id'
          AND ei.identifier = ${authId}
          AND ei.deleted_at IS NULL
          AND et.slug = ${MEMBER_ENTITY_TYPE_SLUG}
          AND e.deleted_at IS NULL
        LIMIT 1
      `;
    }

    if (memberRows.length === 0 && authId) {
      const userRows = await sql`SELECT email FROM "user" WHERE id = ${ctx.userId} LIMIT 1`;
      const userEmail =
        userRows.length > 0 ? normalizeEmail(userRows[0].email as string | null) : null;
      if (userEmail) {
        memberRows = await sql`
          SELECT e.id
          FROM entity_identities ei
          JOIN entities e ON e.id = ei.entity_id
          JOIN entity_types et ON et.id = e.entity_type_id
          WHERE ei.organization_id = ${ctx.organizationId}
            AND ei.namespace = 'email'
            AND ei.identifier = ${userEmail}
            AND ei.deleted_at IS NULL
            AND et.slug = ${MEMBER_ENTITY_TYPE_SLUG}
            AND e.deleted_at IS NULL
          LIMIT 1
        `;
        if (memberRows.length > 0) {
          const memberId = Number(memberRows[0].id);
          await sql`
            INSERT INTO entity_identities (
              organization_id, entity_id, namespace, identifier, source_connector
            ) VALUES (
              ${ctx.organizationId}, ${memberId}, 'auth_user_id', ${authId}, 'save_content'
            )
            ON CONFLICT (organization_id, namespace, identifier) WHERE deleted_at IS NULL
            DO NOTHING
          `;
          logger.info(
            { memberId, userId: ctx.userId, email: userEmail },
            '$member linked via email → auth_user_id claim'
          );
        }
      }
    }

    if (memberRows.length > 0) {
      const memberId = Number(memberRows[0].id);
      if (!finalEntityIds.includes(memberId)) {
        finalEntityIds.push(memberId);
      }
    }
  }

  // 4b. Stamp the source CHANNEL entity when this save originates from a chat
  //     session (worker-originated, carries team + channel in sourceContext).
  //     This makes distilled channel knowhow inherit the channel's per-member
  //     visibility gate (resource-visibility) instead of being org-visible —
  //     so a member of #eng recalls what the agent learned there, but #exec
  //     knowhow never leaks into #eng recall. Best-effort: a channel with no
  //     graphed entity (never synced) resolves to null and the save proceeds
  //     with the existing org/$member scoping.
  const channelEntityId = await resolveChannelEntityId(
    ctx.organizationId,
    ctx.sourceContext?.platform,
    ctx.sourceContext?.teamId,
    ctx.sourceContext?.channelId,
    sql
  );
  if (channelEntityId !== null && !finalEntityIds.includes(channelEntityId)) {
    finalEntityIds.push(channelEntityId);
  }

  // 5. Validate supersedes target exists and belongs to this org
  if (args.supersedes_event_id) {
    // Superseding a `guidance` target stamps its superseded_by, removing it
    // from every prompt — the same effect as delete_knowledge. Authorship is
    // admin-gated, so removal must be too, regardless of the NEW row's kind
    // (a member could otherwise erase guidance by superseding it with a note).
    await assertCanRemoveGuidance(
      ctx.organizationId,
      [args.supersedes_event_id],
      ctx.memberRole
    );
    const existing = await sql`
      SELECT id FROM events
      WHERE id = ${args.supersedes_event_id}
        AND organization_id = ${ctx.organizationId}
    `;
    if (existing.length === 0) {
      // Stale supersede target (already gone / wrong org) is a user fault, not
      // an infra error — ToolUserError so it doesn't fire a Sentry alert.
      throw new ToolUserError(
        `Cannot supersede event ${args.supersedes_event_id}: not found in this organization`,
        404
      );
    }
    const superseding = await sql`
      SELECT id FROM events
      WHERE supersedes_event_id = ${args.supersedes_event_id}
      LIMIT 1
    `;
    if (superseding.length > 0) {
      throw new ToolUserError(
        `Cannot supersede event ${args.supersedes_event_id}: already superseded by event ${superseding[0].id}`,
        409
      );
    }
  }

  // 6. Insert into events
  const externalId = `uc_${crypto.randomUUID()}`;

  let row: Awaited<ReturnType<typeof insertEvent>>;
  try {
    row = await insertEvent({
      entityIds: finalEntityIds,
      organizationId: ctx.organizationId,
      originId: externalId,
      title: args.title,
      payloadType,
      content: args.content ?? null,
      payloadData: args.payload_data,
      payloadTemplate: args.payload_template ?? null,
      attachments: args.attachments,
      authorName: args.author,
      sourceUrl: args.source_url ?? null,
      // The schema promises "Defaults to now if omitted" — honor it. A NULL
      // occurred_at makes the event invisible to watcher windows (window
      // content filters on occurred_at within [window_start, window_end)).
      occurredAt: args.occurred_at ?? new Date().toISOString(),
      semanticType,
      metadata: args.metadata,
      createdBy: ctx.userId,
      clientId: ctx.clientId,
      supersedesEventId: args.supersedes_event_id ?? null,
    });
  } catch (error) {
    // The "already superseded?" SELECT above is non-atomic: two concurrent
    // supersedes of the same target both pass the read, both INSERT, and the
    // loser hits the partial unique index idx_events_superseded_by with a raw
    // 23505. The unique index protects the invariant (no data loss) — surface
    // it as a clean 409 user error instead of a raw DB error + Sentry alert.
    if (
      args.supersedes_event_id &&
      isSupersededByUniqueViolation(error)
    ) {
      throw new ToolUserError(
        `Cannot supersede event ${args.supersedes_event_id}: already superseded by a concurrent write`,
        409
      );
    }
    throw error;
  }

  // 6b. Auto-link: scan content for entity name mentions.
  // Awaited so the background work doesn't outlive the tool call and reject
  // into an unhandled promise after the DB pool has been torn down.
  if (finalEntityIds.length > 0) {
    await autoLinkEvent({
      eventId: Number(row.id),
      entityIds: finalEntityIds,
      content: args.content ?? '',
      title: args.title,
      organizationId: ctx.organizationId,
    }).catch((err) => {
      logger.warn({ err, eventId: row.id }, 'autoLinkEvent failed');
    });
  }

  logger.info(
    {
      id: row.id,
      entity_ids: finalEntityIds,
      semantic_type: semanticType,
      supersedes: args.supersedes_event_id,
    },
    'Content saved via save_memory'
  );

  // Track watcher reaction if attribution source is provided
  if (args.behavior_source) {
    await trackWatcherReaction({
      organizationId: ctx.organizationId,
      watcherId: args.behavior_source.behavior_id,
      windowId: args.behavior_source.window_id,
      reactionType: 'content_saved',
      toolName: 'save_memory',
      toolArgs: { entity_ids: finalEntityIds, semantic_type: semanticType, title: args.title },
      entityId: finalEntityIds[0],
    }).catch((err) => {
      logger.warn({ err, behaviorSource: args.behavior_source }, 'trackWatcherReaction failed');
    });
  }

  // Probe real semantic-index readiness for this specific event rather than
  // asserting a fixed 'pending'. `needsEmbeddingSql` is the same predicate the
  // embed backfill and worker use, so callers can never disagree with the
  // pipeline on what "indexed" means. Embeddings are usually produced by the
  // async backfill (so this is 'pending'), but when one is supplied inline the
  // row is already searchable — reporting a hardcoded 'pending' would be wrong.
  const savedId = Number(row.id);
  const [readiness] = await sql`
    SELECT ${sql.unsafe(needsEmbeddingSql('e', getConfiguredEmbeddingModel()))} AS needs_embedding
    FROM events e WHERE e.id = ${savedId}
  `;
  const searchable = readiness ? !readiness.needs_embedding : false;

  const result: SaveContentResult = {
    id: savedId,
    entity_ids: Array.isArray(row.entity_ids) ? row.entity_ids.map(Number) : finalEntityIds,
    title: row.title as string | null,
    semantic_type: semanticType,
    created_at: String(row.created_at),
    // Row is committed by now; exact reads by id are available from this instant.
    durable_at: String(row.created_at),
    indexing_status: searchable ? 'completed' : 'pending',
    searchable,
		// `knowledge.read` takes `content_ids` (array) — a singular `content_id`
		// is rejected as an unknown argument, so the self-documenting hint must
		// use the exact shape the reader accepts.
		exact_read: {
			method: 'client.knowledge.read',
			content_ids: [savedId],
		},
  };
  if (args.supersedes_event_id) {
    result.supersedes_event_id = args.supersedes_event_id;
  }

  const viewUrl = await buildEventViewUrl(ctx, result.id);
  if (viewUrl) {
    result.view_url = viewUrl;
  }

  return result;
}

import type { CardElement } from "chat";
import { getDb, pgTextArray } from "../db/client";
import { resolveBoundChannelRows } from "../gateway/channels/bound-channels";
import { getChatInstanceManager, isLobuGatewayRunning } from "../lobu/gateway";
import logger from "../utils/logger";
import { resolveSlackUserIdForUser } from "../lobu/stores/chat-identity.js";

interface CreateNotificationParams {
	organizationId: string;
	type:
		| "action_approval_needed"
		| "connection_permission_request"
		| "invitation_received"
		| "browser_auth_expired"
		| "generic"
		| "agent_message";
	title: string;
	body?: string | null;
	resourceType?: string | null;
	resourceId?: string | null;
	resourceUrl?: string | null;
	/** When set, deliver only through this specific bot connection */
	connectionId?: string | null;
	/** When set, deliver only to this Behavior-subscribed channel. */
	channelId?: string | null;
	/** Optional workspace/team guard for channel-scoped delivery. */
	teamId?: string | null;
	/**
	 * Lobu user who owns the change under review (field-change approvals).
	 * When set, bot delivery tries the owner's Slack DM FIRST — resolved via
	 * the owner's workspace-scoped Slack identity — and only falls back
	 * to the configured-target/org-wide channel chain when the owner has no
	 * Slack identity or the DM fails. In-app inbox targeting is unaffected.
	 */
	ownerUserId?: string | null;
	/**
	 * Optional rich card (`chat` `CardElement`) for bot-connection delivery. When
	 * set, the bound channel gets this card instead of the markdown body; the
	 * in-app inbox entry still uses title/body.
	 */
	card?: CardElement | null;
	/**
	 * Optional entity ids to anchor the notification event to (e.g. a watcher's
	 * canvas entity, so the notification threads under the canvas). Stamped onto
	 * the notification event's `entity_ids`.
	 */
	entityIds?: number[];
}

/**
 * Forward a notification to the org's active chat-bot connections so it lands
 * in the bound channel — e.g. a watcher digest posting to #leads.
 *
 * Resolves connections + their Behavior subscriptions straight from Postgres and
 * posts in-process via the chat manager. Every app pod loads every active
 * connection at boot, so the locally-held instance can post regardless of
 * which pod fired the notification — correct under N>1 replicas, no cross-pod
 * routing needed.
 *
 * Best-effort: a connection with no live instance or no binding is skipped
 * without failing the others. A connection bound to several channels posts to
 * each.
 */
interface BotDeliveryTarget {
	connectionId: string;
	platform: string;
	/** Platform-prefixed channel id ready for `chat.channel()`, e.g. "slack:C0123ABCD". */
	channelKey: string;
	/** Workspace/team id from the subscription — keys the owner-DM identity lookup. */
	teamId: string | null;
}

/**
 * Resolve where a notification should be posted.
 *
 * Two branches, UNIONed:
 *
 *   (A) The org's OWN active chat connections JOINed to their subscriptions,
 *       scoped to (org, agent) — the multi-tenant default. A connection with no
 *       subscription has no target; several subscribed channels yield one
 *       target each.
 *
 *   (B) Hosted-preview cross-org delivery. The hosted preview bot is ONE
 *       connection living in its OWN org under a placeholder agent, that fans
 *       out to agents across MANY orgs — a `/lobu link <code>` writes the
 *       subscription under the claim's org, never the connection's. So branch (A)'s
 *       `(org, agent)` JOIN misses it on BOTH columns and proactive
 *       notifications silently drop. This branch resolves the org's bindings
 *       through the shared preview connection, mirroring the inbound
 *       concrete-connection routing. It is gated HARD to the single previewMode
 *       connection per platform and, when that connection is workspace-scoped,
 *       to bindings from the same workspace. It is NOT joined on `agent_id`, so
 *       the hosted connection's placeholder agent does not hide tenant bindings.
 *
 * A legacy tenantless hosted connection can serve all of its bindings. A
 * workspace-scoped hosted connection serves only bindings carrying that same
 * team id, so channel ids cannot collide across workspaces.
 *
 * Exported for testing the delivery path against a real DB.
 */
export async function resolveBotDeliveryTargets(
	organizationId: string,
	opts?:
		| string
		| null
		| {
				connectionId?: string | null;
				channelId?: string | null;
				teamId?: string | null;
		  },
): Promise<BotDeliveryTarget[]> {
	const connectionId =
		typeof opts === "string" || opts === null ? opts : opts?.connectionId;
	const channelId =
		typeof opts === "object" && opts !== null ? opts.channelId : null;
	const teamId = typeof opts === "object" && opts !== null ? opts.teamId : null;
	// Org-wide (no agentId): every channel any of the org's agents is bound to,
	// resolved through the right connection. Shared resolver = one home for the
	// cross-org preview invariant (see bound-channels.ts).
	const rows = await resolveBoundChannelRows(getDb(), {
		organizationId,
		connectionId,
	});

	const normalizedChannelId = channelId
		? channelId.includes(":")
			? channelId
			: null
		: null;

