/**
 * Reaction for the `reconciliation-monitor` Behavior.
 *
 * Persists variance events when unreconciled transactions or new anomalies
 * are detected during the daily reconciliation pass.
 */
import type { ReactionClient, ReactionContext } from "@lobu/connector-sdk";

// Plain JSON Schema (no TypeBox — importing it into a reaction bundle breaks the
// isolate's SDK client proxy). The host validates `ctx.extracted_data` against
// this before the reaction runs, so the handler just reads it with a TS cast.
export const input = {
  type: "object",
  properties: {
    unreconciled_count: { type: "number" },
    new_variances: { type: "array", items: { type: "string" } },
    approaching_deadlines: { type: "array", items: { type: "string" } },
    payment_risks: { type: "array", items: { type: "string" } },
  },
  required: ["unreconciled_count", "new_variances", "approaching_deadlines"],
};

interface ReconciliationData {
  unreconciled_count: number;
  new_variances: string[];
  approaching_deadlines: string[];
  payment_risks?: string[];
}

export default async (
  ctx: ReactionContext,
  client: ReactionClient
): Promise<void> => {
  const data = ctx.extracted_data as ReconciliationData;

  const hasIssues =
    data.unreconciled_count > 0 ||
    (data.new_variances?.length ?? 0) > 0 ||
    (data.approaching_deadlines?.length ?? 0) > 0;

  if (!hasIssues) return;

  const parts: string[] = [];
  if (data.unreconciled_count > 0) {
    parts.push(`${data.unreconciled_count} unreconciled transactions`);
  }
  if (data.new_variances?.length) {
    parts.push(`Variances: ${data.new_variances.join("; ")}`);
  }
  if (data.approaching_deadlines?.length) {
    parts.push(`Deadlines: ${data.approaching_deadlines.join("; ")}`);
  }

  await client.knowledge.save({
    entity_ids: ctx.entities.map((e) => e.id),
    content: parts.join("\n"),
    semantic_type: "reconciliation_alert",
    metadata: {
      window_id: ctx.window.id,
      unreconciled_count: data.unreconciled_count,
      variance_count: data.new_variances?.length ?? 0,
    },
  });
};
/**
 * Integration: extractReactionInputSchema reads a reaction's exported `input`
 * (a PLAIN JSON Schema object) by loading the compiled module in the isolate
 * WITHOUT invoking the handler. This is how a reaction watcher's extraction
 * contract is derived so the worker is told the shape the host validates
 * extracted_data against. Reactions declare `input` as plain JSON Schema (no
 * typebox — it breaks the isolate client; see reaction-execute-typebox.test.ts).
 *
 * Compiles real TS in the isolate runner (no DB needed).
 */

import { describe, expect, it } from 'vitest';
import { extractReactionInputSchema } from '../../../watchers/reaction-executor';

const REACTION_WITH_INPUT = `
import type { ReactionContext, ReactionClient } from "@lobu/connector-sdk";

export const input = {
  type: "object",
  properties: {
    outcome: { enum: ["placed", "manual"] },
    restaurant: { type: "string" },
  },
  required: ["outcome"],
};

interface Input { outcome: "placed" | "manual"; restaurant?: string; }

export default async function (ctx: ReactionContext, client: ReactionClient) {
  const data = ctx.extracted_data as Input;
  return { ok: data.outcome };
}
`;

const REACTION_NO_INPUT = `
export default async function (ctx: any, client: any) {
  return { ok: true };
}
`;

describe('extractReactionInputSchema', () => {
  it('extracts the exported plain JSON Schema input', async () => {
    const schema = await extractReactionInputSchema(REACTION_WITH_INPUT);
    expect(schema).not.toBeNull();
    expect(schema?.type).toBe('object');
    const props = schema?.properties as Record<string, unknown> | undefined;
    expect(props).toBeTruthy();
    expect(props).toHaveProperty('outcome');
    expect(props).toHaveProperty('restaurant');
    expect(() => JSON.stringify(schema)).not.toThrow();
    expect(JSON.stringify(schema)).toContain('"required"');
  });

  it('returns null when the reaction declares no input export (free-form fallback)', async () => {
    expect(await extractReactionInputSchema(REACTION_NO_INPUT)).toBeNull();
  });
});
// ---------------------------------------------------------------------------

/**
 * The shape a Behavior reaction module's default export must satisfy:
 * `export default async (ctx, client, params?) => …`. Used to type-check the
 * `<Handler>` generic on {@link reactionFromFile} against the referenced module.
 */
export type ReactionHandler = (
  ctx: ReactionContext,
  client: ReactionClient,
  params?: Record<string, unknown>
) => Promise<unknown>;

/**
 * A local reaction source file to compile + run in a sandboxed isolate when the
 * Behavior fires. Built with {@link reactionFromFile} and set on
 * {@link Behavior.reaction}. Like {@link ConnectorSource}, this carries only the
 * path as plain data — the handler module is NOT imported at config-eval time;
 * `lobu apply` reads the raw source and the server compiles it.
 */
export interface ReactionSource {
  readonly kind: "reactionSource";
  /** Path to a `*.reaction.ts`, relative to the config file. */
  path: string;
}

/**
 * Reference a local reaction source file to compile + ship at apply time.
 *
