export function isHomeFeedNoise(body: string): boolean {
  if (!body || body.trim().length < 30) return true;
  if (/\bPromoted\b/i.test(body.slice(0, 130))) return true;
  if (/\bSuggested\b/i.test(body.slice(0, 30))) return true;
  // Platform self-promo cards only when there is no real member header
  // (no connection-degree " • " and no expanded "Author" badge). A genuine
  // post that *discusses* LinkedIn Ads must not be dropped.
  const text = body.replace(/^feed post\s+/i, "").trim();
  const hasMemberHeader = text.includes(" • ") || /^\S.+\s+Author\b/.test(text);
  if (!hasMemberHeader) {
    if (/\b(?:Try )?LinkedIn Ads\b/i.test(body)) return true;
    if (/\bGet more leads with boosting\b/i.test(body)) return true;
    if (/\bBoost your best content on LinkedIn\b/i.test(body)) return true;
  }
  return false;
}

/**
 * Map cs_scrape home-feed rows to event envelopes. The componentkey token is
 * not a numeric activity id, so there is no /feed/update permalink — source_url
 * stays at /feed/. Home-feed posts expose no reliable timestamp, so the caller
 * stamps occurred_at with the sync time.
 */
export function buildHomeFeedEvents(
  rows: HomeFeedRow[],
  occurredAt: Date
): EventEnvelope[] {
  const seen = new Set<string>();
  const events: EventEnvelope[] = [];
  for (const row of rows) {
    if (!row?.id || !row.body || seen.has(row.id)) continue;
    if (isHomeFeedNoise(row.body)) continue;
    seen.add(row.id);
    const parsedAuthor = parseHomeFeedAuthorDetails(row.body);
    // Clean DOM author the same way as banner actors so emoji-prefixed names
    // still match (e.g. DOM "🦔 Deb" vs banner actor "Deb").
    const domAuthor = cleanHomeFeedDisplayName(
      (row.author ?? "").trim().split(" • ")[0] ?? ""
    );
    const actorBanner =
      parsedAuthor.banner?.kind === "actor" ? parsedAuthor.banner : null;
    const controlAuthor = parseAuthorControlLabel(row.author_control_label);
    // A phrase such as "We Love This Company" can resemble an engagement
    // banner. When available, the control-menu author disambiguates it without
    // depending on which profile link appears first. Older results fall back to
    // comparing the banner actor with the first visible profile name.
    let banner = parsedAuthor.banner;
    if (actorBanner && controlAuthor) {
      if (nameKey(parsedAuthor.author) !== nameKey(controlAuthor))
        banner = null;
    } else if (
      actorBanner &&
      domAuthor &&
      actorBanner.actor.localeCompare(domAuthor, undefined, {
        sensitivity: "accent",
      }) !== 0
    ) {
      banner = null;
    }
    // The control-menu label names the post author independently of link order
    // and body parsing. Older extension results lack it, so retain the existing
    // body/DOM fallback.
    const author =
      controlAuthor ||
      (banner ? parsedAuthor.author : "") ||
      domAuthor ||
      parsedAuthor.author;

    // Resolve slugs by matching a NAME to the anchor's accessible name, never by
    // link order. The control-menu label names the true author on observed card
    // shapes; the banner names the engager. Each maps to at most one /in/ slug
    // — a company author or an unlinked member simply resolves to none.
    const links = normalizeHomeFeedLinks(row.links);
    const profileUrlFor = (s: string) => `https://www.linkedin.com/in/${s}`;
    const engagement = banner?.kind === "actor" ? banner : null;
    const authorSlug = resolveMemberSlug(links, author);
    const engagerSlug = engagement
      ? resolveMemberSlug(links, engagement.actor)
      : undefined;
    const metadata: Record<string, unknown> = { author };
    if (engagement) {
      metadata.social_actor = engagement.actor;
      metadata.social_action = engagement.action;
      if (engagerSlug) {
        metadata.social_actor_slug = engagerSlug;
        metadata.social_actor_profile_url = profileUrlFor(engagerSlug);
      }
    }
    if (authorSlug) {
      metadata.author_linkedin_slug = authorSlug;
      metadata.author_profile_url = profileUrlFor(authorSlug);
    }

    events.push({
      origin_id: `li_home_${row.id}`,
      payload_text: row.body,
      author_name: author,
      // Feed posts expose no reliable timestamp; use the sync time.
      occurred_at: occurredAt,
      origin_type: "post",
      // Token id is NOT a numeric activity id, so we cannot build a
      // urn:li:activity permalink — link to the feed itself.
      source_url: "https://www.linkedin.com/feed/",
      metadata,
    });
  }
  return events;
}

/**
 * Pull the chrome action dispatcher from sessionState. The connector-worker
 * subprocess (child-runner.ts) splices a live `chrome_dispatcher` object
 * onto every sync's sessionState; the dispatcher's `dispatch()` rides an
 * IPC channel up to the daemon and out to the gateway's
 * /api/workers/dispatch-chrome-action bridge. When no paired Owletto
 * extension is online in the connection's org, the bridge returns the
 * `failed` status and the dispatcher throws — we surface that as the sync
 * failure verbatim.
 */
function requireExtensionDispatcher(ctx: {
  sessionState?: Record<string, unknown> | null;
}): ChromeActionDispatcher {
  const handle = (
    ctx.sessionState as Record<string, unknown> | null | undefined
  )?.chrome_dispatcher as ChromeActionDispatcher | undefined;
  if (!handle || typeof handle.dispatch !== "function") {
    throw new Error(
      "LinkedIn connector requires a paired Owletto Chrome extension. No chrome_dispatcher was injected into sessionState — re-run on a connector-worker that has the dispatcher bridge."
    );
  }
  return handle;
}

