import path from 'node:path';
import type { ProxyOptions } from 'vite';
import { TanStackRouterVite } from '@tanstack/router-plugin/vite';
import react from '@vitejs/plugin-react';
import { defineConfig } from 'vite';

/**
 * Optional same-origin reverse-proxy to a remote Lobu API (usually prod).
 *
 * Setting `VITE_API_URL=https://app.lobu.ai` does *not* work for interactive
 * login: session cookies are Host/Domain-scoped to the API origin (and often
 * `Secure` + `AUTH_COOKIE_DOMAIN=.lobu.ai`), so the SPA on localhost never
 * receives them. Point the SPA at itself (no VITE_API_URL) and proxy `/api`
 * instead — cookies land on localhost and subsequent fetches stay same-origin.
 *
 *   LOBU_API_PROXY=https://app.lobu.ai bun run dev -- --host localhost --port 5173
 *
 * Full-page gateway navigations (App install `/lobu/.../install`) do **not**
 * go through this proxy: `appInstallUrl` uses `VITE_GATEWAY_URL` (injected from
 * `LOBU_API_PROXY` below) so OAuth starts on the real gateway whose
 * `redirect_uri` is registered with the provider.
 *
 * Auth options on the SPA origin:
 *   - `?lobu_token=<PAT>` handoff (from `lobu login` against the cloud context)
 *   - login through the `/api` proxy when better-auth allows it
 */
function prodApiProxy(): Record<string, ProxyOptions> | undefined {
  const target = process.env.LOBU_API_PROXY?.trim();
  if (!target) return undefined;

  const rewriteCookies: NonNullable<ProxyOptions['configure']> = (proxy) => {
    proxy.on('proxyRes', (proxyRes) => {
      const raw = proxyRes.headers['set-cookie'];
      if (!raw) return;
      const list = Array.isArray(raw) ? raw : [raw];
      // Prod cookies often carry Domain=.lobu.ai (or similar). Drop Domain so
      // the cookie becomes host-only for the SPA origin (localhost). Keep the
      // Secure flag: Better Auth names the session `__Secure-…`, which browsers
      // reject unless Secure is set (http://localhost is a secure context).
      proxyRes.headers['set-cookie'] = list.map((cookie) =>
        cookie
          .replace(/;\s*Domain=[^;]*/gi, '')
          .replace(/;\s*SameSite=None/gi, '; SameSite=Lax'),
      );
    });
  };

  const shared: ProxyOptions = {
    target,
    changeOrigin: true,
    secure: true,
    ws: true,
    configure: rewriteCookies,
  };

  return {
    // XHR/fetch + cookies stay same-origin on the SPA host.
    '/api': shared,
    '/oauth': shared,
    '/connect': shared,
  };
}

const lobuApiProxy = process.env.LOBU_API_PROXY?.trim() || '';

export default defineConfig({
  appType: 'spa',
  // src/main.tsx uses a top-level `await` to halt SPA boot during the
  // PAT-in-URL handoff redirect. Vite's default target (es2020 + safari14)
  // doesn't allow top-level await, so prod builds fail in esbuild's
  // transpile step. Bump to esnext — every browser we ship to (Chromium ≥89,
  // Safari ≥15, Firefox ≥90) supports top-level await natively.
  build: {
    target: 'esnext',
    // Workspace packages resolve to their real paths outside node_modules.
    // Include their compiled output so Rollup transforms CommonJS exports
    // before those modules reach a browser chunk.
    commonjsOptions: {
      include: [/node_modules/, /packages[\\/][^\\/]+[\\/]dist/],
    },
  },
  // Split SPA → remote gateway: bake the gateway origin so App install links
  // leave the Vite host and hit the host that owns OAuth redirect_uris.
  // Empty string in co-hosted prod / `make dev` → appInstallUrl stays relative.
  define: {
    'import.meta.env.VITE_GATEWAY_URL': JSON.stringify(lobuApiProxy),
  },
  plugins: [
    TanStackRouterVite({
      routesDirectory: './src/app',
      generatedRouteTree: './src/routeTree.gen.ts',
      // Split each route's component into its own lazy chunk so the initial
      // bundle only carries the router shell + the landed route, not all 37
      // route trees. One flag instead of hand-maintaining .lazy.tsx files.
      autoCodeSplitting: true,
    }),
    react(),
  ],
  resolve: {
    alias: {
      '@': path.resolve(__dirname, './src'),
      // @lobu/core ships CJS dist (`module: CommonJS`). Vite dev would otherwise
      // serve dist/*.js raw over ESM (`exports is not defined`). Point the
      // browser at source — same as the package's `"bun"` export condition.
      // ONLY browser-safe subpaths (errors, reserved). Never alias the package
      // root: the barrel re-exports logger/otel/sentry and would crash the SPA
      // with `process is not defined`.
      '@lobu/core/errors': path.resolve(__dirname, '../core/src/errors.ts'),
      '@lobu/core/reserved': path.resolve(__dirname, '../core/src/reserved.ts'),
    },
  },
  optimizeDeps: {
    // If anything else hits @lobu/core CJS dist, force prebundle interop.
    include: ['@lobu/core/errors', '@lobu/core/reserved', '@shadcn/react/message-scroller'],
  },
  server: {
    // Prefer `localhost` over 127.0.0.1 when using LOBU_API_PROXY so Secure-cookie
    // quirks and better-auth trustedOrigins line up with the common dev host.
    allowedHosts: true,
    proxy: prodApiProxy(),
    hmr: process.env.VITE_HMR_HOST
      ? {
          host: process.env.VITE_HMR_HOST,
          clientPort: Number(process.env.VITE_HMR_CLIENT_PORT || 8443),
          protocol: process.env.VITE_HMR_PROTOCOL || 'wss',
        }
      : undefined,
  },
});
