	// One list, not two. This used to render its own copy of every operation
	// with a tri-state control, directly above `ActionRunner`, which listed the
	// same operations again with a static "Requires approval" badge read off the
	// connector default — so the two could disagree about the same action. The
	// selector now lives on the row you were already looking at.
	const { data: operations = [] } = useConnectorOperations(
		connection.connector_key,
	);
	const updateConnection = useUpdateConnection();
	const persistedModes = readActionModes(connection.config);
	const [draft, setDraft] =
		useState<Record<string, ActionMode>>(persistedModes);
	const [dirty, setDirty] = useState(false);
	// Reset when the connection swaps. `useState` seeds once, so without this a
	// draft made on one connection stays on screen for the next — and Save
	// writes it into the wrong connection's config. Keyed on `connection.id`
	// only: depending on `persistedModes` would clobber an in-progress edit
	// every time the connection refetches.
	// biome-ignore lint/correctness/useExhaustiveDependencies: reset on connection swap, not on every refetch
	useEffect(() => {
		setDraft(readActionModes(connection.config));
		setDirty(false);
	}, [connection.id]);

	if (operations.length === 0) return null;

	const handleModeChange = (operationKey: string, mode: ActionMode) => {
		setDraft((prev) => ({ ...prev, [operationKey]: mode }));
		setDirty(true);
	};

	const handleSave = () => {
		const nextConfig = {
			...(connection.config ?? {}),
			action_modes: draft,
		} as Record<string, unknown>;
		updateConnection.mutate(
			{ connection_id: connection.id, config: nextConfig },
			{ onSuccess: () => setDirty(false) },
		);
	};

	return (
		<div className="space-y-3">
			<p className="text-xs text-muted-foreground">
				Inherits the connector's default policy. Disabled hides an action from
				the agent, requires approval prompts you first, auto-approve runs
				without confirmation.
			</p>
			<ActionRunner
				connectionId={connection.id}
