/**
 * Tool: notify
 *
 * Send notifications to organization members from agents.
 *
 * Actions:
 * - send: Send a notification to org members
 */

import { type Static, Type } from '@sinclair/typebox';
import type { CardElement } from 'chat';
import { getDb, pgTextArray } from '../../db/client';
import { WATCHER_CANVAS_NAMESPACE } from '../../utils/canvas-events';
import { emit } from '../../events/emitter';
import { createNotificationForUsers } from '../../notifications/service';
import logger from '../../utils/logger';
import { trackWatcherReaction } from '../../utils/watcher-reactions';
import type { ToolContext } from '../registry';
import { action, defineActionTool } from './action-tool';

// ============================================
// Schema
// ============================================

const SendAction = Type.Object({
  action: Type.Literal('send'),
  title: Type.String({ description: 'Notification title', maxLength: 200 }),
  body: Type.Optional(Type.String({ description: 'Notification body text', maxLength: 1000 })),
  recipients: Type.Optional(
    Type.Union(
      [
        Type.Literal('admins'),
        Type.Literal('all'),
        Type.Array(Type.String({ description: 'User ID' })),
      ],
      {
        default: 'admins',
        description:
          "Who to notify. 'admins' (default): org admins/owners. 'all': all org members. Or an array of specific user IDs.",
      }
    )
  ),
  resource_url: Type.Optional(
    Type.String({ description: 'Relative URL to link the notification to (e.g. /acme/entities)' })
  ),
  idempotency_key: Type.Optional(
    Type.String({
      minLength: 1,
      maxLength: 300,
      description:
        'Stable producer key. Repeating a send with the same key returns success without creating or delivering a duplicate.',
    })
  ),
  connection_id: Type.Optional(
    Type.String({
      description:
        'Connection ID for targeted delivery (e.g. Telegram bot connection). When set, notification is delivered through this specific bot connection.',
    })
  ),
  data: Type.Optional(
    Type.Record(Type.String(), Type.Any(), {
      description: 'Arbitrary JSON payload stored in notification body as formatted JSON',
    })
  ),
  card: Type.Optional(
    Type.Record(Type.String(), Type.Any(), {
      description:
        'A `chat` CardElement (built with the card primitives) for rich bot-connection delivery. When set, the bound channel gets this card instead of the markdown body.',
    })
  ),
  behavior_source: Type.Optional(
    Type.Object(
      {
        behavior_id: Type.Number({ description: 'Behavior that triggered this notification' }),
        window_id: Type.Number({ description: 'Window that triggered this notification' }),
      },
      { description: 'Attribution source when notification is triggered by a Behavior reaction' }
    )
  ),
});

// ============================================
// Handler
// ============================================

const notifyTool = defineActionTool('notify', {
  send: action(SendAction, handleSend),
});

export const NotifySchema = notifyTool.schema;
export const notify = notifyTool.run;

async function handleSend(
  args: Static<typeof SendAction>,
  ctx: ToolContext
): Promise<{ notified_count: number }> {
  const sql = getDb();
  const recipients = args.recipients ?? 'admins';

  let userIds: string[];
  if (Array.isArray(recipients)) {
    // Validate that the provided user IDs are actual members of the org
    const rows = await sql<{ userId: string }>`
      SELECT "userId"
      FROM "member"
      WHERE "organizationId" = ${ctx.organizationId}
        AND "userId" = ANY(${pgTextArray(recipients)}::text[])
    `;
    userIds = rows.map((r) => r.userId);
  } else if (recipients === 'all') {
    const rows = await sql<{ userId: string }>`
      SELECT "userId"
      FROM "member"
      WHERE "organizationId" = ${ctx.organizationId}
    `;
    userIds = rows.map((r) => r.userId);
  } else {
    // 'admins' (default)
    const rows = await sql<{ userId: string }>`
      SELECT "userId"
      FROM "member"
      WHERE "organizationId" = ${ctx.organizationId}
        AND role IN ('admin', 'owner')
    `;
    userIds = rows.map((r) => r.userId);
  }

  if (userIds.length === 0) {
    return { notified_count: 0 };
  }

  // Build body: prefer explicit body, append data as JSON if provided
  let body = args.body ?? null;
  if (args.data) {
    const dataStr = JSON.stringify(args.data, null, 2);
    body = body ? `${body}\n\n${dataStr}` : dataStr;
  }

  // Anchor watcher-sourced notifications to the watcher's canvas entity so they
  // thread under the canvas. behavior_source is caller input, so validate the
  // (watcher_id, window_id) pair against the caller's org before anchoring —
  // otherwise any org member could thread a notification under an unrelated
  // watcher's canvas. Resolve the lazy canvas entity via its entity_identities
  // claim; a mismatched pair or a watcher with no canvas yet anchors nothing.
  let canvasEntityIds: number[] | undefined;
  if (args.behavior_source) {
    const rows = await getDb()<{ entity_id: number | string }>`
      SELECT ei.entity_id
      FROM entity_identities ei
      JOIN watchers w
        ON w.id = ${args.behavior_source.behavior_id}
       AND w.organization_id = ${ctx.organizationId}
      WHERE ei.organization_id = ${ctx.organizationId}
        AND ei.namespace = ${WATCHER_CANVAS_NAMESPACE}
        AND ei.identifier = ${String(args.behavior_source.behavior_id)}
        AND ei.deleted_at IS NULL
        AND (
          ${args.behavior_source.window_id ?? null}::bigint IS NULL
          OR EXISTS (
            -- window_id is the canvas ROOT event id; validate the pair.
            SELECT 1 FROM canvas_windows ww
            WHERE ww.id = ${args.behavior_source.window_id ?? null}
              AND ww.watcher_id = w.id
          )
        )
      LIMIT 1
    `;
    if (rows.length > 0) canvasEntityIds = [Number(rows[0].entity_id)];
  }

  const notification = await createNotificationForUsers(userIds, {
    organizationId: ctx.organizationId,
    type: 'agent_message',
    title: args.title,
    body,
    resourceUrl: args.resource_url ?? null,
    idempotencyKey: args.idempotency_key ?? null,
    connectionId: args.connection_id ?? null,
    card: (args.card as CardElement | undefined) ?? null,
    entityIds: canvasEntityIds,
  });

  if (notification.created) {
    emit(ctx.organizationId, { keys: ['notifications', 'notifications-unread-count'] });
  }

  // Track watcher reaction if attribution source is provided
  if (notification.created && args.behavior_source) {
    await trackWatcherReaction({
      organizationId: ctx.organizationId,
      watcherId: args.behavior_source.behavior_id,
      windowId: args.behavior_source.window_id,
      reactionType: 'notification_sent',
      toolName: 'notify',
      toolArgs: { title: args.title, recipients: args.recipients },
    }).catch((err) => {
      logger.warn({ err, behaviorSource: args.behavior_source }, 'trackWatcherReaction failed');
    });
  }

  return { notified_count: userIds.length };
}

/**
 * Generic factory for action-discriminated admin tools.
 *
 * The `manage_*` tools all share the same shape: an `action` discriminator,
 * a per-action handler, and dispatch via `routeAction` (which enforces the
 * per-action access policy). This module lets a tool declare itself as a map
 * of `action -> { schema, handler }` instead of hand-rolling that plumbing.
 *
 * Two flavors, matching the two schema shapes that exist today:
 *
 * - `defineActionTool` — for tools whose input schema is a `Type.Union` of
 *   per-action variants (one `Type.Object` with an `action` literal each).
 *   The factory derives the union schema from the declared variants, so the
 *   exposed JSON schema is identical to the previous hand-written
 *   `Type.Union([...])` as long as variants are declared in the same order.
 *   Args are coerced + validated against the matched variant before dispatch
 *   (`withValidatedArgs`), so per-action required fields come from the schema.
 *
 * - `defineFlatActionTool` — for tools that intentionally expose a single
 *   flat object schema with an `action` enum (kept flat for MCP clients and
 *   because the registry's per-action public/access filtering only applies
 *   to union variants — flattening a union here would change the exposed
 *   schema). The flat schema stays declared in the tool file; the factory
 *   only provides dispatch + required-field checks.
 *
 * Handler signature is `(args, ctx, env)` — `ctx` before `env` because most
 * handlers need the context but not the environment, and trailing unused
 * params can simply be omitted.
 */

import type { Static, TObject, TUnion } from '@sinclair/typebox';
import { Type } from '@sinclair/typebox';
import type { Env } from '../../index';
import type { ToolContext } from '../registry';
import { withValidatedArgs } from '../validate-args';
import { requireField, routeAction } from './action-router';

interface ActionDefinition<S extends TObject = TObject, R = unknown> {
  /** TypeBox variant for this action (must carry the `action` literal). */
  schema: S;
  handler: (args: Static<S>, ctx: ToolContext, env: Env) => Promise<R>;
}

/** Pair an action's TypeBox variant with its typed handler. */
export function action<S extends TObject, R>(
  schema: S,
  handler: (args: Static<S>, ctx: ToolContext, env: Env) => Promise<R>
): ActionDefinition<S, R> {
  return { schema, handler };
}

type AnyActions = Record<string, ActionDefinition<any, any>>;

type ArgsOf<T extends AnyActions> = Static<T[keyof T]['schema']>;
type ResultOf<T extends AnyActions> = Awaited<ReturnType<T[keyof T]['handler']>>;

function runActions<T extends AnyActions>(
  toolName: string,
  actions: T,
  args: ArgsOf<T>,
  env: Env,
  ctx: ToolContext
): Promise<ResultOf<T>> {
  const record = args as Record<string, unknown> & { action: string };
  const handlers: Record<string, () => Promise<ResultOf<T>>> = {};
  for (const [name, def] of Object.entries(actions)) {
    handlers[name] = () => def.handler(args, ctx, env);
  }
  return routeAction<ResultOf<T>>(toolName, record.action, ctx, handlers);
}

/**
 * Define a union-schema action tool. Returns the derived `Type.Union` input
 * schema (variants in declaration order) and the `(args, env, ctx)` runner
 * used as the registry handler. The runner coerces + validates args against
 * the matched action variant before dispatch (lobu#1137), so per-action
 * required fields are enforced by the schema, not `requires` lists.
 */
export function defineActionTool<T extends AnyActions>(
  toolName: string,
  actions: T
): {
  schema: TUnion<Array<T[keyof T]['schema']>>;
  run: (args: ArgsOf<T>, env: Env, ctx: ToolContext) => Promise<ResultOf<T>>;
} {
  const schema = Type.Union(Object.values(actions).map((def) => def.schema)) as TUnion<
    Array<T[keyof T]['schema']>
  >;
  return {
    schema,
    run: withValidatedArgs(toolName, schema, (args: ArgsOf<T>, env: Env, ctx: ToolContext) =>
      runActions(toolName, actions, args, env, ctx)
    ),
  };
}

/**
 * Define a flat-schema action tool: the tool keeps its hand-written flat
 * object schema; the factory provides typed dispatch + required-field checks.
 * Actions missing from the map fail with `Unknown action: ...` (routeAction).
 */
export function defineFlatActionTool<TArgs extends { action: string }, R>(
  toolName: string,
  actions: {
    [A in TArgs['action']]?: {
      requires?: string[];
      handler: (args: TArgs, ctx: ToolContext, env: Env) => Promise<R>;
    };
  }
): (args: TArgs, env: Env, ctx: ToolContext) => Promise<R> {
  return (args, env, ctx) => {
    const record = args as Record<string, unknown> & { action: string };
    const handlers: Record<string, () => Promise<R>> = {};
    for (const [name, def] of Object.entries(actions) as Array<
      [string, { requires?: string[]; handler: (args: TArgs, ctx: ToolContext, env: Env) => Promise<R> }]
    >) {
      handlers[name] = () => {
        for (const field of def.requires ?? []) {
          requireField(record[field], field, name);
        }
        return def.handler(args, ctx, env);
      };
    }
    return routeAction<R>(toolName, args.action, ctx, handlers);
  };
}

/** Shorthand for a flat-tool action entry. */
export function flatAction<TArgs extends { action: string }, R>(
  handler: (args: TArgs, ctx: ToolContext, env: Env) => Promise<R>,
  options?: { requires?: string[] }
): { requires?: string[]; handler: (args: TArgs, ctx: ToolContext, env: Env) => Promise<R> } {
  return { handler, requires: options?.requires };
}
